import{_ as a,a as t,c as n,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 42 Recording an earthquake","description":"学习 被动语态中的时态与体，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 42 Recording an earthquake","description":"学习 被动语态中的时态与体，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 被动语态中的时态与体，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 41 Training elephants","link":"/life/english/new-concept/book-4/unit-06/lesson-041"},"next":{"text":"第四册：流利英语 · Lesson 43 Are there strangers in space?","link":"/life/english/new-concept/book-4/unit-06/lesson-043"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 41 Training elephants","link":"/life/english/new-concept/book-4/unit-06/lesson-041"},"next":{"text":"第四册：流利英语 · Lesson 43 Are there strangers in space?","link":"/life/english/new-concept/book-4/unit-06/lesson-043"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-06/lesson-042.md","filePath":"life/english/new-concept/book-4/unit-06/lesson-042.md"}'),i={name:"life/english/new-concept/book-4/unit-06/lesson-042.md"};function o(s,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="第四册-流利英语-·-lesson-42-recording-an-earthquake" tabindex="-1">第四册：流利英语 · Lesson 42 Recording an earthquake <a class="header-anchor" href="#第四册-流利英语-·-lesson-42-recording-an-earthquake" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 42 Recording an earthquake&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元 6</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕地震记录学习如何由仪器读数形成解释，区分测得的信号、事件定位和灾害影响。历史仪器描述不代表所有现代设备；本课只训练阅读和记录表达，不用单一图线推断安全结论。重点掌握被动句时态选择，准确说明哪些数据已记录、哪些仍在分析。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>seismograph</td><td>/ˈsaɪzməɡrɑːf/</td><td>n.</td><td>地震仪</td><td>a seismograph record</td></tr><tr><td>vibration</td><td>/vaɪˈbreɪʃən/</td><td>n.</td><td>振动</td><td>detect a vibration</td></tr><tr><td>trace</td><td>/treɪs/</td><td>n.</td><td>记录曲线</td><td>a continuous trace</td></tr><tr><td>instrument</td><td>/ˈɪnstrəmənt/</td><td>n.</td><td>仪器</td><td>a measuring instrument</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>pick up — 检测到微弱信号</li><li>be under review — 正在审查之中</li></ul><h2 id="语法讲解-被动语态中的时态与体" tabindex="-1">语法讲解：被动语态中的时态与体 <a class="header-anchor" href="#语法讲解-被动语态中的时态与体" aria-label="Permalink to &quot;语法讲解：被动语态中的时态与体&quot;">​</a></h2><p>was recorded 表过去一次记录；has been recorded 强调到现在已有记录；is being recorded 表此刻正在记录；had been recorded 表早于另一个过去节点。被动结构的时态由 be 承担，过去分词 recorded 保持不变。不要把 has recorded 与 has been recorded 混淆，前者要求主语是记录者。选择时态时先确定时间参照，再决定是否需要完成或进行含义。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The signal has been recorded, but the data are still being analysed.</p></blockquote><p>信号已经记录下来，但数据仍在分析中。</p><p>has been recorded 表已完成的记录；are being analysed 表正在进行的被动过程；data 在此按复数处理。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The signal has recorded 错把信号当记录者；应使用 has been recorded。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>交替读 has been recorded 和 is being recorded，重点听 been 与 being；用录音判断“已完成”和“正在进行”。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The signal has been stored successfully. Its timing is still being compared with other records. We cannot yet draw a reliable conclusion about the event from this trace alone.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句虚构仪器报告：已获取内容、正在处理的步骤、尚不能作出的判断。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>被动时态清楚标记处理阶段，末句限定单条记录的解释能力。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：The readings are being ___ now.（check）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> checked</p><p><strong>解析：</strong> 现在进行时被动为 are being + 过去分词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例中已经完成的是记录还是分析？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 记录。</p><p><strong>解析：</strong> has been recorded 已完成，being analysed 仍进行。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 The technician recorded the signal yesterday. 改为被动。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The signal was recorded by the technician yesterday.</p><p><strong>解析：</strong> yesterday 对应一般过去时被动 was recorded。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：被动语态中的时态与体。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-041">上一课</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-06/lesson-043">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",o]]);export{u as __pageData,b as default};
